require_once __DIR__.'/operations.php';require_role('owner_admin');header('Content-Type: application/json; charset=utf-8');
try{
if(!isset($kpiSection))throw new RuntimeException('Unknown KPI section.');$zone=new DateTimeZone('Africa/Windhoek');$today=new DateTimeImmutable('today',$zone);$period=(string)($_GET['period']??'today');switch($period){case'yesterday':$from=$today->modify('-1 day');$to=$from;break;case'this_week':$from=$today->modify('monday this week');$to=$today;break;case'last_week':$from=$today->modify('monday last week');$to=$from->modify('+6 days');break;case'this_month':$from=$today->modify('first day of this month');$to=$today;break;case'last_month':$from=$today->modify('first day of last month');$to=$from->modify('last day of this month');break;case'custom':$from=new DateTimeImmutable((string)($_GET['date_from']??''),$zone);$to=new DateTimeImmutable((string)($_GET['date_to']??''),$zone);break;default:$period='today';$from=$today;$to=$today;}if($to<$from)throw new RuntimeException('Invalid reporting period.');$settings=[];foreach(ops_rows('SELECT setting_key,setting_value FROM kpi_settings')as$row)$settings[$row['setting_key']]=$row['setting_value'];$dataStart=new DateTimeImmutable($settings['data_start_date']??'2026-07-01',$zone);$adoption=new DateTimeImmutable($settings['adoption_date']??'2026-07-14',$zone);$effective=$from<$dataStart?$dataStart:$from;$rate=$effective<$adoption?$adoption:$effective;$fromSql=$effective->format('Y-m-d 00:00:00');$rateSql=$rate->format('Y-m-d 00:00:00');$toSql=$to->format('Y-m-d 23:59:59');$cards=[];$rows=[];$breakdown=[];
if($kpiSection==='attendance'){$rows=ops_rows("SELECT e.full_name employee,DATE(DATE_ADD(s.login_at,INTERVAL 2 HOUR)) day,MIN(DATE_ADD(s.login_at,INTERVAL 2 HOUR)) first_login,MAX(DATE_ADD(COALESCE(s.logout_at,s.last_seen_at),INTERVAL 2 HOUR)) last_activity,SUM(TIMESTAMPDIFF(MINUTE,s.login_at,COALESCE(s.logout_at,s.last_seen_at)))/60 hours,COUNT(*) sessions FROM kpi_sessions s JOIN ops_employees e ON e.id=s.user_id WHERE s.login_at BETWEEN ? AND ? GROUP BY e.id,DATE(DATE_ADD(s.login_at,INTERVAL 2 HOUR)) ORDER BY day DESC,e.full_name",[$rateSql,$toSql]);$cards=[['label'=>'Attendance records','value'=>count($rows)],['label'=>'Total hours','value'=>round(array_sum(array_column($rows,'hours')),1)]];}
elseif($kpiSection==='orders'){$rows=ops_rows("SELECT o.order_number,o.customer_name,o.status,o.payment_status,o.total_amount,se.old_status,se.new_status,se.changed_at,e.full_name employee FROM kpi_status_events se JOIN ops_orders o ON o.id=se.record_id LEFT JOIN ops_employees e ON e.id=se.changed_by WHERE se.module='order' AND se.changed_at BETWEEN ? AND ? ORDER BY se.changed_at DESC LIMIT 500",[$fromSql,$toSql]);$summary=ops_rows("SELECT COUNT(*) total,SUM(status='completed') completed,SUM(payment_status='paid') paid,COALESCE(SUM(total_amount),0) revenue FROM ops_orders WHERE created_at BETWEEN ? AND ?",[$fromSql,$toSql])[0]??[];$cards=[['label'=>'Orders','value'=>(int)($summary['total']??0)],['label'=>'Completed','value'=>(int)($summary['completed']??0)],['label'=>'Paid','value'=>(int)($summary['paid']??0)],['label'=>'Revenue','value'=>(float)($summary['revenue']??0),'format'=>'currency']];}
elseif($kpiSection==='packing-performance'){$rows=ops_rows("SELECT p.item_name,p.weight_class,p.quantity_planned,p.priority,p.packing_status,p.date_loaded,p.date_started,p.date_completed,e.full_name employee,TIMESTAMPDIFF(MINUTE,p.date_loaded,p.date_started) queue_minutes,TIMESTAMPDIFF(MINUTE,p.date_started,p.date_completed) active_minutes FROM ops_packing_tasks p LEFT JOIN ops_employees e ON e.id=p.assigned_employee_id WHERE p.date_loaded BETWEEN ? AND ? AND p.deleted_at IS NULL ORDER BY p.date_loaded DESC LIMIT 500",[$fromSql,$toSql]);$summary=ops_rows("SELECT COUNT(*) items,SUM(packing_status IN ('done','website','packed_label_needed','done_needs_label','label_created')) completed,AVG(CASE WHEN date_completed>=date_started THEN TIMESTAMPDIFF(MINUTE,date_started,date_completed) END) avg_active,AVG(CASE WHEN date_started>=date_loaded THEN TIMESTAMPDIFF(MINUTE,date_loaded,date_started) END) avg_queue FROM ops_packing_tasks WHERE date_loaded BETWEEN ? AND ? AND deleted_at IS NULL",[$fromSql,$toSql])[0]??[];$completed=(int)($summary['completed']??0);$cards=[['label'=>'Items','value'=>(int)($summary['items']??0)],['label'=>'Completed','value'=>$completed],['label'=>'Avg active time','value'=>$completed>=5?$summary['avg_active']:null,'format'=>'minutes','sample'=>$completed],['label'=>'Workflow queue time','value'=>$completed>=5?$summary['avg_queue']:null,'format'=>'minutes','sample'=>$completed]];$breakdown=ops_rows("SELECT e.full_name employee,COUNT(*) raw_items,SUM(CASE p.weight_class WHEN 'S' THEN ? WHEN 'M' THEN ? WHEN 'L' THEN ? WHEN 'XL' THEN ? ELSE ? END) weighted_points,AVG(CASE WHEN p.date_completed>=p.date_started THEN TIMESTAMPDIFF(MINUTE,p.date_started,p.date_completed)/(CASE p.weight_class WHEN 'S' THEN ? WHEN 'M' THEN ? WHEN 'L' THEN ? WHEN 'XL' THEN ? ELSE ? END) END) avg_minutes_per_point,SUM(p.weight_class IN ('L','XL'))*100/COUNT(*) high_weight_percent FROM ops_packing_tasks p JOIN ops_employees e ON e.id=p.assigned_employee_id WHERE p.date_loaded BETWEEN ? AND ? AND p.deleted_at IS NULL GROUP BY p.assigned_employee_id,e.full_name ORDER BY weighted_points DESC",[(float)($settings['weight_points_s']??1),(float)($settings['weight_points_m']??3),(float)($settings['weight_points_l']??6),(float)($settings['weight_points_xl']??10),(float)($settings['weight_points_m']??3),(float)($settings['weight_points_s']??1),(float)($settings['weight_points_m']??3),(float)($settings['weight_points_l']??6),(float)($settings['weight_points_xl']??10),(float)($settings['weight_points_m']??3),$fromSql,$toSql]);}
elseif($kpiSection==='bookkeeping'){$rows=ops_rows("SELECT r.recon_date,r.system_balance,r.counted_total,r.variance,r.variance_note,r.created_at,e.full_name employee FROM hambelela_cashbook_recon r LEFT JOIN ops_employees e ON e.id=r.logged_by WHERE r.recon_date BETWEEN ? AND ? ORDER BY r.recon_date DESC",[$effective->format('Y-m-d'),$to->format('Y-m-d')]);$cards=[['label'=>'Cash-up days','value'=>count($rows)],['label'=>'Total variance','value'=>array_sum(array_column($rows,'variance')),'format'=>'currency']];}
elseif($kpiSection==='waybills'){$rows=ops_rows("SELECT w.waybill_reference,w.customer_name,w.status,w.uploaded_at,w.due_by,w.sent_at,TIMESTAMPDIFF(MINUTE,w.uploaded_at,w.sent_at) duration_minutes,e.full_name employee FROM hambelela_waybills w LEFT JOIN ops_employees e ON e.id=w.sent_by WHERE w.uploaded_at BETWEEN ? AND ? AND w.deleted_at IS NULL ORDER BY w.uploaded_at DESC LIMIT 500",[$fromSql,$toSql]);$summary=ops_rows("SELECT COUNT(*) total,SUM(status='sent') sent,SUM(status IN ('pending','overdue') AND due_by<NOW()) overdue,AVG(TIMESTAMPDIFF(MINUTE,uploaded_at,sent_at)) avg_minutes FROM hambelela_waybills WHERE uploaded_at BETWEEN ? AND ? AND deleted_at IS NULL",[$fromSql,$toSql])[0]??[];$cards=[['label'=>'Waybills','value'=>(int)($summary['total']??0)],['label'=>'Sent','value'=>(int)($summary['sent']??0)],['label'=>'Overdue pending','value'=>(int)($summary['overdue']??0)],['label'=>'Avg created to sent','value'=>$summary['avg_minutes'],'format'=>'minutes']];}
elseif($kpiSection==='task-management'){$rows=ops_rows("SELECT t.task_name,t.priority,t.status,t.created_at,t.deadline,t.completed_at,e.full_name employee FROM ops_checklist_tasks t LEFT JOIN ops_employees e ON e.id=t.assigned_employee_id WHERE t.created_at BETWEEN ? AND ? AND t.deleted_at IS NULL ORDER BY t.created_at DESC LIMIT 500",[$fromSql,$toSql]);$summary=ops_rows("SELECT COUNT(*) total,SUM(status IN ('complete','completed','approved')) done,SUM(status NOT IN ('complete','completed','approved') AND deadline<NOW()) overdue FROM ops_checklist_tasks WHERE created_at BETWEEN ? AND ? AND deleted_at IS NULL",[$fromSql,$toSql])[0]??[];$cards=[['label'=>'Tasks','value'=>(int)($summary['total']??0)],['label'=>'Done','value'=>(int)($summary['done']??0)],['label'=>'Overdue','value'=>(int)($summary['overdue']??0)]];}
elseif($kpiSection==='website-updates'){$rows=ops_rows("SELECT p.item_name,p.date_completed done_at,p.frontdesk_website_updated_at updated_at,TIMESTAMPDIFF(MINUTE,p.date_completed,p.frontdesk_website_updated_at) lag_minutes,e.full_name employee FROM ops_packing_tasks p LEFT JOIN ops_employees e ON e.id=p.frontdesk_website_updated_by WHERE p.frontdesk_website_updated_at BETWEEN ? AND ? ORDER BY p.frontdesk_website_updated_at DESC LIMIT 500",[$rateSql,$toSql]);$cards=[['label'=>'Updates','value'=>count($rows)],['label'=>'Avg update lag','value'=>$rows?array_sum(array_column($rows,'lag_minutes'))/count($rows):null,'format'=>'minutes']];}
elseif($kpiSection==='errors-quality'){$rows=ops_rows("SELECT l.error_title,l.category,l.severity,l.cause,l.status,l.logged_at,l.resolution,e.full_name employee FROM ops_error_logs l LEFT JOIN ops_employees e ON e.id=l.employee_id WHERE l.logged_at BETWEEN ? AND ? AND l.deleted_at IS NULL ORDER BY l.logged_at DESC LIMIT 500",[$fromSql,$toSql]);$cards=[['label'=>'Errors logged','value'=>count($rows)],['label'=>'Employee caused','value'=>count(array_filter($rows,static fn($r)=>$r['cause']==='employee'))],['label'=>'Resolved','value'=>count(array_filter($rows,static fn($r)=>$r['status']==='resolved'))]];}
elseif($kpiSection==='audit-log'){$rows=ops_rows("SELECT l.created_at,l.action,l.entity_type,l.entity_id,l.metadata,l.ip_address,e.full_name employee FROM ops_activity_logs l LEFT JOIN ops_employees e ON e.id=l.employee_id WHERE l.created_at BETWEEN ? AND ? ORDER BY l.created_at DESC LIMIT 500",[$fromSql,$toSql]);$cards=[['label'=>'Recorded actions','value'=>count($rows)]];}
elseif($kpiSection==='hr-leave'){$rows=ops_rows("SELECT CONCAT(e.first_name,' ',e.last_name) employee,l.leave_type,l.start_date,l.end_date,l.days,l.status,l.created_at FROM leave_requests l JOIN employees e ON e.id=l.employee_id WHERE l.start_date<=? AND l.end_date>=? ORDER BY l.created_at DESC LIMIT 500",[$to->format('Y-m-d'),$effective->format('Y-m-d')]);$cards=[['label'=>'Leave requests','value'=>count($rows)],['label'=>'Approved days','value'=>array_sum(array_column(array_filter($rows,static fn($r)=>$r['status']==='approved'),'days'))],['label'=>'Pending','value'=>count(array_filter($rows,static fn($r)=>$r['status']==='pending'))]];}
else{$employees=ops_rows("SELECT e.full_name employee,r.name role_name,CASE WHEN r.role_key='packer' THEN CONCAT('Weighted points: ',COALESCE(p.points,0),' · Raw items: ',COALESCE(p.items,0)) ELSE CONCAT('Hours recorded: ',ROUND(COALESCE(s.hours,0),1)) END role_relative_evidence FROM ops_employees e JOIN ops_roles r ON r.id=e.role_id LEFT JOIN(SELECT user_id,SUM(TIMESTAMPDIFF(MINUTE,login_at,COALESCE(logout_at,last_seen_at)))/60 hours FROM kpi_sessions WHERE login_at BETWEEN ? AND ? GROUP BY user_id)s ON s.user_id=e.id LEFT JOIN(SELECT assigned_employee_id,COUNT(*) items,SUM(CASE weight_class WHEN 'S' THEN 1 WHEN 'M' THEN 3 WHEN 'L' THEN 6 WHEN 'XL' THEN 10 ELSE 3 END)points FROM ops_packing_tasks WHERE date_loaded BETWEEN ? AND ? AND deleted_at IS NULL GROUP BY assigned_employee_id)p ON p.assigned_employee_id=e.id WHERE e.status='active' AND r.role_key<>'owner_admin' ORDER BY r.role_key,e.full_name",[$rateSql,$toSql,$fromSql,$toSql]);$rows=$employees;$cards=[['label'=>'Employees','value'=>count($rows)]];}
